/// Transform the first `count` of `ordered` candidate card uids into fresh
/// `target_id` cards in place (reusing the pile slot), upgrading each iff
/// `upgraded`.
///
/// CHARGE / GUARDS open a C# `CardSelectCmd` transform grid (select N →
/// `CardCmd.Transform`/`TransformTo`). The parity harness auto-resolves
/// such a grid with the option-0 prefix — `range(min(max(min_select,1),
/// len))` of the grid — on BOTH engines, and the transform itself reads no
/// RNG, so applying that prefix directly is byte-equivalent to opening the
/// choice and draining it.
pub(crate) fn transform_first_n_to(
    state: &mut CombatState,
    ordered: &[sts2_core::CardUid],
    count: usize,
    target_id: CardId,
    upgraded: bool,
) {
    for &uid in ordered.iter().take(count) {
        if let Some(card) = crate::cards::spec_index::card_pod_from_id(target_id, upgraded) {
            let _ = sts2_core::card_effects::transform_card_in_place(state, uid, card);
        }
    }
}

