/// Find every `CardId::SovereignBlade` across the requested piles.
/// Walks pile slices directly (no allocation outside the returned vec).
pub(crate) fn collect_blade_uids(
    state: &CombatState,
    include_exhaust: bool,
) -> Vec<sts2_core::CardUid> {
    let mut out = Vec::new();
    for &uid in state
        .player
        .hand
        .iter()
        .chain(state.player.draw.iter())
        .chain(state.player.discard.iter())
        .chain(state.player.play.iter())
    {
        let idx = uid.0.get() as usize - 1;
        if let Some(card) = state.cards.get(idx) {
            if card.card_id == CardId::SovereignBlade {
                out.push(uid);
            }
        }
    }
    if include_exhaust {
        for &uid in &state.player.exhaust {
            let idx = uid.0.get() as usize - 1;
            if let Some(card) = state.cards.get(idx) {
                if card.card_id == CardId::SovereignBlade {
                    out.push(uid);
                }
            }
        }
    }
    out
}

/// Public Forge primitive — see module-level forge-pipeline doc above.
///
/// Returns the number of blades that were buffed (after the ensure-step).
/// The return is informational; canonical Python returns `None`. Callers
/// that want to assert "at least one blade got buffed" can check
/// `>= 1` after a successful forge.
///
/// `forger` is the `CreatureUid` of the creature performing the forge.
/// At this pin only the player can forge; the parameter is kept for
/// parity with the Python signature. `_source_card` is the `CardUid` of
/// the card that called forge (or `None` for power-triggered forges);
/// it is currently informational and threaded into `ForgeCtx` only as
/// the `source_listener` discriminator (always `None` for card-triggered
/// forges since there is no listener identity for a card).
///
/// Bead `sts2-rs-5o9w`. Port pin
/// `sts2-rl-agent@01c094d:sts2_env/core/combat.py:L2023-L2042`.
pub fn combat_forge(
    state: &mut CombatState,
    forger: CreatureUid,
    amount: i32,
    _source_card: Option<sts2_core::CardUid>,
) -> usize {
    forge_for(state, forger, amount, false)
}

/// [`combat_forge`]'s body. `from_hammer_time`: this forge is a co-op
/// teammate's Hammer Time answering another player's forge (C# `source is
/// HammerTimePower`), which no Hammer Time passes on again.
fn forge_for(
    state: &mut CombatState,
    forger: CreatureUid,
    amount: i32,
    from_hammer_time: bool,
) -> usize {
    if amount <= 0 {
        return 0;
    }
    // Player-only gate. If the player creature uid is initialised and the
    // forger is some other creature, no-op (canonical Python gate
    // `_is_player_side_player(owner)`).
    if let Some(player_uid) = state.player.creature_uid {
        if player_uid != forger {
            return 0;
        }
        // Alive guard.
        if let Some(c) = state.creatures.iter().find(|c| c.id == player_uid.0) {
            if c.current_hp <= 0 {
                return 0;
            }
        }
    }

    // Step 1 — ensure at least one active blade.
    let active = collect_blade_uids(state, /* include_exhaust */ false);
    if active.is_empty() {
        let blade = card_from_spec(&sspecs::sovereign_blade());
        // C# `ForgeCmd.Forge` adds the first blade via
        // `CardPileCmd.AddGeneratedCardToCombat(.., addedByPlayer: true)`
        // UNCONDITIONALLY — including the turn-start `FurnacePower` forge, when
        // the play pile is EMPTY. Plain `spawn_card_into_hand`'s play-pile
        // heuristic would read `addedByPlayer = false` there and silently drop
        // the `AfterCardGeneratedForCombat` reactions (ArsenalPower Strength,
        // PillarOfCreationPower Block) — Regent fuzz seed 42: a turn-start
        // Furnace forge failed to grant Arsenal(1) Strength. Force `true`.
        // Bead `sts2-rs-potion-gen-arsenal`.
        let new_blade =
            sts2_core::card_effects::spawn_card_into_hand_with_origin(state, blade, true);
        // C# `SwordSagePower.AfterCardEnteredCombat`: a SovereignBlade that
        // enters combat while the player holds SwordSage inherits the power's
        // amount as `BaseReplayCount` (Replay N). Existing blades got their
        // replay from `AfterPowerAmountChanged` when SwordSage was played; this
        // syncs blades forged afterwards. The freshly spawned blade starts at
        // replay 0, so set (not add) it to the SwordSage amount.
        let sword_sage = state
            .player_power_amount(sts2_core::powers::PowerKind::SwordSage)
            .max(0);
        if sword_sage > 0 {
            let idx = new_blade.0.get() as usize - 1;
            if let Some(card) = state.cards.get_mut(idx) {
                card.base_replay_count = sword_sage;
            }
        }
    }

    // SeekingEdge flips every SovereignBlade to AllEnemies targeting (C#
    // `SovereignBlade.TargetType => HasSeekingEdge ? AllEnemies : AnyEnemy`).
    // The blade's `target_type` is a per-card field read by both the
    // legal-action enumerator and the play dispatch, so keep it synced here:
    // forge is the only path that creates/touches blades, and the SeekingEdge
    // card forges on play (after applying the power), so every blade existing
    // when SeekingEdge becomes active is reached by this loop.
    let seeking_edge = state.player_power_amount(sts2_core::powers::PowerKind::SeekingEdge) > 0;
    let blade_target = if seeking_edge {
        sts2_core::cards::TargetType::AllEnemies
    } else {
        sts2_core::cards::TargetType::Enemy
    };

    // Step 2 — buff every blade across every pile (incl. exhaust).
    let all_blades = collect_blade_uids(state, /* include_exhaust */ true);
    for uid in &all_blades {
        let idx = uid.0.get() as usize - 1;
        if let Some(card) = state.cards.get_mut(idx) {
            // Python defaults `base_damage` to 10 if missing; the spec
            // already initialises base_damage=10 (see
            // `status_specs_generated::sovereign_blade`). Saturating add
            // to stay defensive against over-buffing.
            card.base_damage = card.base_damage.saturating_add(amount);
            card.target_type = blade_target;
        }
    }

    // Step 3 — fire after_forge listeners.
    let ctx = ForgeCtx {
        forger: CreatureRef::Player,
        amount,
        source_listener: None,
    };
    dispatch_after_forge(state, &ctx);

    // Co-op: C# `HammerTimePower.AfterForge` (HammerTimePower.cs:26) makes
    // every other living player Forge the same amount when its owner forges
    // (GH #1004).
    if !from_hammer_time && state.player_power_amount(PowerKind::HammerTime) > 0 {
        sts2_core::coop::each_other_player(state, |state| {
            if let Some(me) = state.player.creature_uid {
                forge_for(state, me, amount, true);
            }
        });
    }

    all_blades.len()
}

/// Convenience wrapper for card handlers: forge `amount` from the
/// resolving card. Reads the player's `creature_uid` (or falls back to
/// a sentinel for legacy fixtures that bypass `init_player_creature`)
/// and forwards the resolving card's uid as the source. Bead
/// `sts2-rs-5o9w`.
pub(crate) fn forge_from_card(state: &mut CombatState, amount: i32) -> usize {
    let forger = state.player.creature_uid.unwrap_or_else(|| {
        // Legacy fallback — combat_forge accepts any uid when no player
        // creature is wired (the gate short-circuits on `if let Some`).
        CreatureUid(NonZeroU32::new(1).expect("non-zero sentinel"))
    });
    let source = sts2_core::card_effects::resolving_card_uid(state);
    combat_forge(state, forger, amount, source)
}

/// Apply `amount` stacks of `kind` to the player slot. Mirrors the
/// local helper in `ironclad.rs` / `silent.rs`; kept module-private
/// because the public surface
/// [`sts2_core::card_effects::apply_power_to_creature`] requires a
/// `CreatureUid` and at this pin not every fixture wires
/// `state.player.creature_uid` (the d03 Phase 1 mirror is opt-in).
/// Direct-arena push matches what Vigor / Strength on player do in
/// the ironclad pool.
pub(crate) fn apply_power_to_player(state: &mut CombatState, kind: PowerKind, amount: i32) {
    // C# `PowerCmd.Apply` returns while the combat `IsEnding` (PowerCmd.cs:69).
    if amount <= 0 || state.is_over || sts2_core::combat_loop::enemy_side_is_ending(state) {
        return;
    }
    // Bead `sts2-rs-au4l2`: route through the canonical creature surface
    // when the d03 mirror is set, so self-powers stack onto the same
    // instance as relic combat-start grants.
    if let Some(uid) = state.player.creature_uid {
        sts2_core::card_effects::apply_power_to_creature(state, uid, kind, amount);
        return;
    }
    let existing_uid = state
        .player
        .powers
        .iter()
        .copied()
        .find(|uid| state.powers.iter().any(|p| p.id == uid.0 && p.kind == kind));
    if let Some(uid) = existing_uid {
        if let Some(pow) = state.powers.get_mut_by_id(uid.0) {
            pow.amount = pow.amount.saturating_add(amount);
        }
        return;
    }
    let next_id_raw = state
        .powers
        .iter()
        .map(|p| p.id.get())
        .max()
        .map_or(1, |m| m.saturating_add(1));
    let new_id = NonZeroU32::new(next_id_raw).expect("power id non-zero");
    state.powers.push(Power {
        id: new_id,
        kind,
        amount,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(PowerUid(new_id));
}

