/// Bead `sts2-rs-qz6v3`: per-CardId static star_cost lookup.
/// Python `sts2-rl-agent@01c094d:sts2_env/cards/regent.py` declares
/// `star_cost` as a per-spec constant set at registration time
/// (`FallingStar=2`, `AstralPulse=3`, `GuidingStar=2`, `Quasar=2`,
/// `Resonance=3`, `TheSmith=4`, `DecisionsDecisions=6`). Since the
/// value is invariant per CardId and never mutated on instances,
/// we expose it as a `CardId → i32` lookup rather than adding a
/// per-instance field to `Card` (which would force a 266-literal
/// refactor across the workspace). The function is the single
/// source of truth read by CrescentSpear and any future star-cost
/// consumers (Stardust special-case, Star-pool relics, etc.).
#[must_use]
pub fn card_star_cost(card_id: CardId) -> i32 {
    // Full `CanonicalStarCost` table — the 21 Regent star cards
    // (`MegaCrit.Sts2.Core.Models.Cards/*.cs`, v0.103.2). CrescentSpear's
    // damage multiplier counts every card with `CanonicalStarCost >= 0`
    // (C# `AllCards.Count(c.CanonicalStarCost >= 0 || c.HasStarCostX)`), so
    // the table MUST be complete — the prior 7-card subset under-counted
    // (missing CrescentSpear itself + 13 others), making SPLASH-generated
    // Crescent Spears deal far too little (seed 1156: 0 vs 12). Mirrors the
    // core `card_base_star_cost` gate table (keep the two in sync). Bead
    // `sts2-rs-qz6v3`.
    match card_id {
        CardId::SevenStars => 7,
        CardId::DecisionsDecisions => 6,
        CardId::Comet | CardId::NeutronAegis | CardId::RoyalGamble => 5,
        CardId::Devastate | CardId::TheSmith => 4,
        CardId::Alignment
        | CardId::AstralPulse
        | CardId::DyingStar
        | CardId::GammaBlast
        | CardId::ReflectCard
        | CardId::Resonance
        | CardId::TheSealedThrone => 3,
        CardId::FallingStar
        | CardId::GuidingStar
        | CardId::MeteorShower
        | CardId::ParticleWall
        | CardId::Quasar => 2,
        CardId::CloakOfStars | CardId::CrescentSpear => 1,
        // v0.111.0: the MP-only Constellation has `CanonicalStarCost => 2`
        // (decomp Models.Cards/Constellation.cs:16), so CrescentSpear counts
        // it. The id exists in no v0.107.1 state; mirrors the core
        // `card_base_star_cost` row (GH #798).
        CardId::Constellation => 2,
        _ => 0,
    }
}

