/// Apply a signed `delta` of `kind` to a `creature_uid` enemy.
/// Mirrors [`apply_power_to_player`] but admits negative stacks,
/// which the [`apply_power_to_creature`] / [`apply_power_to_enemy`]
/// primitive does not — at this pin `Resonance` needs `Strength -1`
/// for every alive enemy. No-op on zero or dead target; folds into
/// an existing instance of the same kind when present, otherwise
/// allocates a new power-row.
///
/// Artifact-aware for negative drains: C# `ArtifactPower` negates ANY
/// application whose `GetTypeForAmount(amount) == Debuff` — for an
/// `AllowNegative` attribute power (Strength) that's the case whenever
/// `delta < 0` — consuming one stack. Resonance's `-1 Strength` to every
/// enemy is exactly such a drain (parity fuzz Regent seed 306: Rust
/// applied `-1 Strength` past each enemy's Artifact). Mirrors the
/// ironclad/silent/colorless `apply_power_signed_to_creature` helpers.
/// Bead `sts2-rs-crush-under-artifact`.
pub(crate) fn add_power_to_enemy_signed(
    state: &mut CombatState,
    target_uid: CreatureUid,
    kind: PowerKind,
    amount: i32,
) {
    // A landed player drain fires SleightOfFlesh & co. (C#
    // `Hook.AfterPowerAmountChanged` runs for silent applies too).
    sts2_core::card_effects::signed_power_apply_with_reactors(
        state,
        target_uid,
        kind,
        amount,
        |s| add_power_to_enemy_signed_raw(s, target_uid, kind, amount),
    );
}

fn add_power_to_enemy_signed_raw(
    state: &mut CombatState,
    target_uid: CreatureUid,
    kind: PowerKind,
    delta: i32,
) {
    if delta == 0 {
        return;
    }
    if delta < 0
        && sts2_core::card_effects::try_consume_artifact_for_signed_debuff(state, target_uid, delta)
    {
        return;
    }
    let Some(creature_idx) = state
        .creatures
        .iter()
        .position(|c| c.id == target_uid.0 && c.current_hp > 0)
    else {
        return;
    };
    let existing_uid = state.creatures[creature_idx]
        .powers
        .iter()
        .copied()
        .find(|uid| state.powers.iter().any(|p| p.id == uid.0 && p.kind == kind));
    if let Some(uid) = existing_uid {
        // C# `PowerCmd.cs:248-251`: after every amount change, an
        // `AllowNegative` attribute power (Strength/Dexterity/Focus) whose
        // amount lands at exactly 0 is removed
        // (`PowerModel.ShouldRemoveDueToAmount`, `PowerModel.cs:480-491`).
        // Netting e.g. a +1 Strength to 0 via CrushUnder's internal
        // TemporaryStrengthPower fold must PRUNE the instance, not leave a
        // 0-amount Strength lingering (parity fuzz Regent seed 868:
        // TurretOperator gained +1 Strength via ReloadMove, then CrushUnder's
        // -1 netted it to 0; C# removed it -> powers.len=1, Rust left it ->
        // powers.len=2). Mirrors the canonical core helper
        // `apply_signed_attr_power` (card_effects.rs).
        let mut remove_pid = None;
        if let Some(pow) = state.powers.get_mut_by_id(uid.0) {
            pow.amount = pow.amount.saturating_add(delta);
            if pow.amount == 0
                && matches!(
                    kind,
                    PowerKind::Strength | PowerKind::Dexterity | PowerKind::Focus
                )
            {
                remove_pid = Some(uid.0);
            }
        }
        if let Some(pid) = remove_pid {
            state.powers.retain(|p| p.id != pid);
            state.player.powers.retain(|u| u.0 != pid);
            for c in &mut state.creatures {
                c.powers.retain(|u| u.0 != pid);
            }
        }
        return;
    }
    let next_id_raw = state
        .powers
        .iter()
        .map(|p| p.id.get())
        .max()
        .map_or(1, |m| m.saturating_add(1));
    let new_id = NonZeroU32::new(next_id_raw).expect("power id non-zero");
    state.powers.push(Power {
        id: new_id,
        kind,
        amount: delta,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.creatures[creature_idx].powers.push(PowerUid(new_id));
}

