/// in the static spec. C# source of truth `FallingStar.cs`:
/// `DamageVar(8)` (bead `sts2-rs-nntl0` corrected base_damage 7 -> 8).
#[must_use]
pub const fn falling_star() -> crate::cards::types::CardSpec {
    use sts2_core::cards::{CardType, TargetType};

    use crate::cards::types::{CardEffect, CardRarity, CardSpec};

    CardSpec {
        id: CardId::FallingStar,
        name: "FALLING_STAR",
        cost: 0,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        rarity: CardRarity::Basic,
        base_damage: 8,
        effect: CardEffect::DealDamage { base: 8 },
        ..CardSpec::base()
    }
}

/// Venerate CardSpec factory — bead `sts2-rs-3kyp`. Cost 1 Skill /
/// Self, no damage / no block — grants 2 Stars (Regent resource
/// gained via [`play_venerate`] in POOL). Per
/// `sts2-rl-agent@01c094d:sts2_env/cards/regent.py:L901-L908
/// make_venerate`.
#[must_use]
pub const fn venerate() -> crate::cards::types::CardSpec {
    use sts2_core::cards::{CardType, TargetType};

    use crate::cards::types::{CardRarity, CardSpec};

    CardSpec {
        id: CardId::Venerate,
        name: "VENERATE",
        cost: 1,
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        rarity: CardRarity::Basic,
        ..CardSpec::base()
    }
}

/// Build the **10-card** Regent starter deck: 4×StrikeRegent,
/// 4×DefendRegent, 1×FallingStar, 1×Venerate. Mirrors
/// `create_regent_starter_deck` at
/// `sts2-rl-agent@01c094d:sts2_env/cards/regent.py`. Added by bead
/// `sts2-rs-s39` to unblock the d19 fuzz harness extension.
#[must_use]
pub fn regent_starter_deck() -> Vec<crate::cards::types::CardSpec> {
    let mut deck = Vec::with_capacity(10);
    for _ in 0..4 {
        deck.push(strike_regent());
    }
    for _ in 0..4 {
        deck.push(defend_regent());
    }
    deck.push(falling_star());
    deck.push(venerate());
    deck
}

/// Late-effect for `MakeItSo` — fired by
/// [`card_effects::fire_late_effects`] after every card play. Mirrors
/// Python's `make_it_so_late` at `sts2-rl-agent@01c094d:
/// sts2_env/cards/regent.py:L780-L794`.
///
/// Behaviour (single-player Rust port; Python's multi-owner check is
/// elided since there's exactly one player):
///
/// 1. Skip if the triggering play is not a Skill.
/// 2. Skip if the watched MakeItSo card is already in hand (Python's
///    `if watched in combat.hand: return`).
/// 3. Read the interval from the watched card's
///    `combat_vars[MakeItSoInterval]` slot (default 3).
/// 4. If `combat.skills_played_this_turn % interval == 0`, scan
///    Discard / Exhaust / Draw and move the watched card to hand.
pub(crate) fn make_it_so_late_effect(
    state: &mut CombatState,
    watched_uid: sts2_core::CardUid,
    played_ctx: &sts2_core::hooks::CardCtx,
) {
    use sts2_core::cards::{CardType, VarKey};

    if played_ctx.card_type != Some(CardType::Skill) {
        return;
    }
    if state.player.hand.contains(&watched_uid) {
        return;
    }
    let idx = watched_uid.0.get() as usize - 1;
    let Some(card) = state.cards.get(idx) else {
        return;
    };
    let interval = card.combat_var(VarKey::MakeItSoInterval);
    let interval: u32 = if interval > 0 {
        // Cast is safe: positive i32 fits in u32 for the realistic
        // range of `cards: 3` (and any future upgrade values).
        u32::try_from(interval).unwrap_or(3)
    } else {
        3
    };
    // Count from the WIRE-CARRIED bucket, not the private duplicate.
    // C# counts `History.CardPlaysFinished` filtered to this turn's Skills
    // (`MakeItSo.cs:40`), and `player.cards_played_this_turn` is that same
    // per-type tally — it crosses `state_to_dict` / `state_from_dict`, while
    // `player.skills_played_this_turn` does not (both constructors init it to
    // 0). Every reconcile therefore zeroed it, `count == 0` short-circuited
    // forever, and a reconstructed Make It So never returned to hand: 14
    // records in the 2026-08-03 live Regent corpus.
    let count = state.count_player_cards_played_this_turn(Some(CardType::Skill));
    if count == 0 || !count.is_multiple_of(interval) {
        return;
    }
    // `CardPileCmd.Add(this, Hand)` (MakeItSo.cs:43) refuses a combat pile
    // once the combat is ending (CardPileCmd.cs:312).
    if sts2_core::combat_loop::combat_is_ending(state) {
        return;
    }
    // Move the watched card from whichever non-Hand pile it occupies
    // back to Hand, with the same overflow-to-discard guard the
    // engine uses elsewhere.
    let _moved = scan_piles_and_move_to_hand(
        state,
        // `_owner` is currently unused inside the helper; pass any
        // CreatureUid sentinel. The single-player engine has one
        // creature_uid for the player but the helper signature
        // accepts a CreatureUid for parity with the future
        // multi-player port.
        state
            .player
            .creature_uid
            .unwrap_or_else(|| CreatureUid::new(1).expect("non-zero")),
        &[PileKind::Discard, PileKind::Exhaust, PileKind::Draw],
        |c| c.uid == watched_uid,
    );
}
